SELECT CAST(p DIV 10000 AS CHAR) AS bucket, CAST(SUM(k) AS CHAR) AS n, SHA2(GROUP_CONCAT(CONCAT(CAST(p AS CHAR), ':', CAST(k AS CHAR), CHAR(10)) ORDER BY p SEPARATOR ''), 256) AS digest, LENGTH(GROUP_CONCAT(CONCAT(CAST(p AS CHAR), ':', CAST(k AS CHAR), CHAR(10)) ORDER BY p SEPARATOR '')) AS bytes, SUM(LENGTH(CONCAT(CAST(p AS CHAR), ':', CAST(k AS CHAR), CHAR(10)))) AS expected_bytes FROM (SELECT person_id AS p, COUNT(*) AS k FROM dsomop_it_636008_0bb1270d_cdm.person WHERE person_id IS NOT NULL GROUP BY person_id) dsomop_membership GROUP BY CAST(p DIV 10000 AS CHAR) ORDER BY MIN(p DIV 10000)
